IF EXISTS (SELECT 1 FROM jsonb_array_elements(e->'variants') x WHERE NOT EXISTS (SELECT 1 FROM catalog.variants r WHERE r.id=(x->>'id')::uuid AND (to_jsonb(r)-'created_at'-'updated_at'-'catalog_version')=x)) THEN RAISE EXCEPTION 'DATA-002 contenido diferente en catalog.variants'; END IF;
IF EXISTS (SELECT 1 FROM jsonb_array_elements(e->'vav') x WHERE NOT EXISTS (SELECT 1 FROM catalog.variant_attribute_values r WHERE r.id=(x->>'id')::uuid AND (to_jsonb(r)-'created_at'-'updated_at'-'catalog_version')=x)) THEN RAISE EXCEPTION 'DATA-002 contenido diferente en catalog.variant_attribute_values'; END IF;
