IF EXISTS (SELECT 1 FROM jsonb_array_elements(e->'pav') x WHERE NOT EXISTS (SELECT 1 FROM catalog.product_attribute_values r WHERE r.id=(x->>'id')::uuid AND (to_jsonb(r)-'created_at'-'updated_at'-'catalog_version')=x)) THEN RAISE EXCEPTION 'DATA-002 contenido diferente en catalog.product_attribute_values'; END IF;
IF EXISTS (SELECT 1 FROM jsonb_array_elements(e->'product_images') x WHERE NOT EXISTS (SELECT 1 FROM catalog.product_images r WHERE r.id=(x->>'id')::uuid AND (to_jsonb(r)-'created_at'-'updated_at'-'catalog_version')=x)) THEN RAISE EXCEPTION 'DATA-002 contenido diferente en catalog.product_images'; END IF;
IF (SELECT count(*) FROM catalog.sku_identity WHERE sku IN ('ADI-ENT22-SHORT-GRI-S','ADI-ENT22-SHORT-GRI-M','ADI-ENT22-SHORT-GRI-L','ADI-ENT26-AZU-S','ADI-ENT26-AZU-M','ADI-ENT26-AZU-L','ADI-ENT26-BLA-S','ADI-ENT26-BLA-M','ADI-ENT26-BLA-L','ADI-MESSI-JI8291-05','ADI-PRED-IG7760-MUL-38','ADI-PRED-IG7760-MUL-40','ADI-PRED-IG7760-MUL-42','ADI-PRED-IG7760-MUL-43','ADI-RUNX-JD9558-NEG-EU3436','ADI-RUNX-JD9558-NEG-EU3739','ADI-RUNX-JD9558-NEG-EU4042','ADI-SQUA25-JG5832-NEG-S','ADI-SQUA25-JG5832-NEG-M','ADI-SQUA25-JG5832-NEG-L','ADI-SQUA25-JH3407-AZU-S','ADI-SQUA25-JH3407-AZU-M','ADI-SQUA25-JH3407-AZU-L','NIK-ACADEMY-HV4386-05','NIK-EVP-FQ0327-NEG-EU3438','NIK-EVP-FQ0327-NEG-EU3842','NIK-EVP-FQ0327-NEG-EU4246','NIK-EVP-FQ0327-BLA-EU3438','NIK-EVP-FQ0327-BLA-EU3842','NIK-EVP-FQ0327-BLA-EU4246','NIK-PARK3-M-BV6855-NEG-S','NIK-PARK3-M-BV6855-NEG-M','NIK-PARK3-M-BV6855-NEG-L','NIK-PARK3-W-BV6860-NEG-XS','NIK-PARK3-W-BV6860-NEG-S','NIK-PARK3-W-BV6860-NEG-M','NIK-PARK3-W-BV6860-NEG-L','NIK-PARK3-W-BV6860-NEG-XL','NIK-PARK7-BV6708-NEG-S','NIK-PARK7-BV6708-NEG-M','NIK-PARK7-BV6708-NEG-L','PUM-SC-782244-BLA-S','PUM-SC-782244-BLA-M','PUM-SC-782244-BLA-L','PUM-ORBITA-084641-05','UA-TECH20-1326413-NEG-S','UA-TECH20-1326413-NEG-M','UA-TECH20-1326413-NEG-L')) <> 48 THEN RAISE EXCEPTION 'DATA-002 triggers no derivaron todos los SKU'; END IF; END $g$;
